// Deployed Worker entry (wrangler.jsonc `main`). Wraps the SvelteKit worker to add:
//  - the thekutners.com/list* -> wishlist.thekutners.com redirect (SPEC §13)
//  - the cron handler, which calls the app's internal job route with a header that
//    external requests can never carry (it is stripped in `fetch`).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated by `vite build` (adapter-cloudflare)
import kit from '../../.svelte-kit/cloudflare/_worker.js';
import { aliasRedirect, isAliasPassthrough } from '../lib/redirect';

const CRON_HEADER = 'x-wishlist-cron';

interface Env {
	CANONICAL_HOST?: string;
	[key: string]: unknown;
}

type KitWorker = {
	fetch(req: Request, env: Env, ctx: ExecutionContext): Promise<Response>;
};
const app = kit as unknown as KitWorker;

export default {
	async fetch(req: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
		const target = aliasRedirect(req.url, env.CANONICAL_HOST || '');
		if (target) return Response.redirect(target, 302);
		// A subrequest to the route's own URL goes to the zone's origin, not back to this Worker.
		if (isAliasPassthrough(req.url, env.CANONICAL_HOST || '')) return fetch(req);
		if (req.headers.has(CRON_HEADER)) {
			return new Response('Forbidden', { status: 403 });
		}
		return app.fetch(req, env, ctx);
	},

	async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
		// "0 9 * * *" is the daily image/offer refresh; everything else is the 15-min sync.
		const kind = controller.cron === '0 9 * * *' ? 'pages' : 'sync';
		const host = (env.CANONICAL_HOST || 'localhost').trim();
		const req = new Request(`https://${host}/api/internal/cron?kind=${kind}`, {
			method: 'POST',
			headers: { [CRON_HEADER]: '1', 'content-type': 'application/json' }
		});
		const res = await app.fetch(req, env, ctx);
		if (!res.ok) console.error('cron job failed', kind, res.status, await res.text());
	}
};
